impl Solution{pub fn is_number(s:String)->bool{let b=s.as_bytes();let(mut num,mut dot,mut exp,mut after)=(false,false,false,true);for i in 0..b.len(){let c=b[i];if c.is_ascii_digit(){num=true;after=true}else if c==b'.'{if dot||exp{return false}dot=true}else if c==b'e'||c==b'E'{if exp||!num{return false}exp=true;after=false}else if c==b'+'||c==b'-'{if i>0&&b[i-1]!=b'e'&&b[i-1]!=b'E'{return false}}else{return false}}num&&after}}
